import{_ as t,c as o,o as a,aj as n}from"./chunks/framework.Id7s26SP.js";const u=JSON.parse('{"title":"Interface: CreateDocumentOptions","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/CreateDocumentOptions.md","filePath":"reference/js-bao-wss-client/api/interfaces/CreateDocumentOptions.md"}'),r={name:"reference/js-bao-wss-client/api/interfaces/CreateDocumentOptions.md"};function c(i,e,d,s,l,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / CreateDocumentOptions</p><h1 id="interface-createdocumentoptions" tabindex="-1">Interface: CreateDocumentOptions <a class="header-anchor" href="#interface-createdocumentoptions" aria-label="Permalink to “Interface: CreateDocumentOptions”">​</a></h1><p>Options for creating a new document.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="documentformat" tabindex="-1">documentFormat? <a class="header-anchor" href="#documentformat" aria-label="Permalink to “documentFormat?”">​</a></h3><blockquote><p><code>optional</code> <strong>documentFormat?</strong>: <code>1</code> | <code>2</code></p></blockquote><p>Create a LARGE document (<code>2</code>) instead of an ordinary one.</p><p>A large document keeps its records in a persisted table on both ends and carries only the current epoch&#39;s changes in its document, so it scales far past an ordinary document&#39;s ~10 MB — at the cost of needing a local store that outlives the session (Node has one; a browser needs <code>databaseConfig: { type: &quot;opfs&quot;, ... }</code>). The choice is made here and is never migrated.</p><p>Omitted — the default — sends nothing, so an ordinary create&#39;s request is exactly what it was before this option existed. <code>1</code> is the ordinary format, named explicitly. Any other value, including the string <code>&quot;2&quot;</code>, is refused with <code>INVALID_ARGUMENT</code> before anything is created, and <code>2</code> with <code>localOnly: true</code> is refused with <code>LOCAL_ONLY_UNSUPPORTED_OPTION</code>.</p><hr><h3 id="localonly" tabindex="-1">localOnly? <a class="header-anchor" href="#localonly" aria-label="Permalink to “localOnly?”">​</a></h3><blockquote><p><code>optional</code> <strong>localOnly?</strong>: <code>boolean</code></p></blockquote><p>If true, the document is created and stays entirely on-device: it is never sent to the server, in the creating session or any later one, and no commit ever applies to it. Open it with <code>documents.open(id, { waitForLoad: &quot;local&quot;, enableNetworkSync: false })</code>; opening it with <code>waitForLoad: &quot;network&quot;</code> or <code>enableNetworkSync: true</code> (the default) throws <code>LOCAL_ONLY_UNSUPPORTED_OPTION</code>.</p><hr><h3 id="metadata" tabindex="-1">metadata? <a class="header-anchor" href="#metadata" aria-label="Permalink to “metadata?”">​</a></h3><blockquote><p><code>optional</code> <strong>metadata?</strong>: <code>unknown</code></p></blockquote><p>Opaque JSON-serializable metadata blob to attach at creation time (≤ 4 KB serialized UTF-8). Note: <code>thumbnailBlobId</code> cannot be set on create — create the document first, upload the blob (which will reference the doc), then call <code>documents.update</code> with <code>thumbnailBlobId</code>.</p><hr><h3 id="tags" tabindex="-1">tags? <a class="header-anchor" href="#tags" aria-label="Permalink to “tags?”">​</a></h3><blockquote><p><code>optional</code> <strong>tags?</strong>: <code>string</code>[]</p></blockquote><p>Tags to attach to the document at creation time.</p><hr><h3 id="title" tabindex="-1">title? <a class="header-anchor" href="#title" aria-label="Permalink to “title?”">​</a></h3><blockquote><p><code>optional</code> <strong>title?</strong>: <code>string</code></p></blockquote><p>The display title for the new document.</p>',27)])])}const m=t(r,[["render",c]]);export{u as __pageData,m as default};
